const getDeviceDetails = () => {
const ua = navigator.userAgent;
let deviceType = "💻 PC (Desktop)";
let osName = "Unknown OS";
let browserName = "Unknown Browser";
if (/Mobi|Android|iPhone|iPad|Windows Phone/i.test(ua)) {
deviceType = /iPad|Tablet/i.test(ua) ? "📟 Tablet" : "📱 Mobile (Phone)";
}
if (/Windows/i.test(ua)) {
osName = "Windows PC";
if (/Windows NT 10.0/i.test(ua)) osName = "Windows 10 / 11 PC";
else if (/Windows NT 6.1/i.test(ua)) osName = "Windows 7 PC";
} else if (/Macintosh|Mac OS X/i.test(ua)) {
const match = ua.match(/Mac OS X ([0-9_.]+)/);
const macVer = match ? `macOS ${match[1].replace(/_/g, '.')}` : "macOS";
osName = `Apple Mac (${macVer})`;
} else if (/iPhone/i.test(ua)) {
const match = ua.match(/iPhone OS ([0-9_]+)/);
const iosVer = match ? `iOS ${match[1].replace(/_/g, '.')}` : "iOS";
osName = `Apple iPhone (${iosVer})`;
} else if (/iPad/i.test(ua)) {
const match = ua.match(/OS ([0-9_]+)/);
const ipadVer = match ? `iPadOS ${match[1].replace(/_/g, '.')}` : "iPadOS";
osName = `Apple iPad (${ipadVer})`;
} else if (/Android/i.test(ua)) {
const realVer = window.clientHintsPlatformVersion ? `Android ${window.clientHintsPlatformVersion.split('.')[0]}` : "";
const realModel = window.clientHintsModel ? ` - ${cleanAndroidModel(window.clientHintsModel)}` : "";
if (realVer || realModel) {
osName = `${realVer || "Android"}${realModel}`;
} else {
const match = ua.match(/Android\s+([0-9.]+)/i);
const osVer = match ? `Android ${match[1]}` : "Android";
let model = "";
const startIdx = ua.indexOf('(');
const endIdx = ua.indexOf(')');
if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
const insideStr = ua.substring(startIdx + 1, endIdx);
const tokens = insideStr.split(';');
for (let token of tokens) {
token = token.trim();
if (/Linux|Android|U|wv|chrome|mobile|safari|version|direct/i.test(token)) continue;
if (token.length > 2) {
model = ` - ${cleanAndroidModel(token)}`;
break;
}
}
}
osName = `${osVer}${model}`;
}
} else if (/Linux/i.test(ua)) {
osName = "Linux PC";
}
if (/Chrome/i.test(ua) && !/Edge|Edg|OPR/i.test(ua)) {
browserName = "Google Chrome";
} else if (/Safari/i.test(ua) && !/Chrome|Edg/i.test(ua)) {
browserName = "Apple Safari";
} else if (/Firefox/i.test(ua)) {
browserName = "Mozilla Firefox";
} else if (/Edg|Edge/i.test(ua)) {
browserName = "Microsoft Edge";
} else if (/OPR|Opera/i.test(ua)) {
browserName = "Opera Browser";
}
return { deviceType, osName, browserName, raw: ua };
};
