(function() {
const canvas = document.getElementById('ambient-particles-canvas');
if (!canvas) return;
const ctx = canvas.getContext('2d');
let width = window.innerWidth;
let height = window.innerHeight;
canvas.width = width;
canvas.height = height;
window.addEventListener('resize', () => {
width = window.innerWidth;
height = window.innerHeight;
canvas.width = width;
canvas.height = height;
});
const sparkles = [];
let mouse = { x: null, y: null, lastX: null, lastY: null, speedX: 0, speedY: 0 };
window.addEventListener('mousemove', (e) => {
mouse.x = e.clientX;
mouse.y = e.clientY;
if (mouse.lastX !== null && mouse.lastY !== null) {
mouse.speedX = mouse.x - mouse.lastX;
mouse.speedY = mouse.y - mouse.lastY;
const dist = Math.hypot(mouse.speedX, mouse.speedY);
if (dist > 2) {
const count = Math.min(Math.floor(dist / 3), 3);
for (let i = 0; i < count; i++) {
const ratio = i / count;
const px = mouse.lastX + mouse.speedX * ratio;
const py = mouse.lastY + mouse.speedY * ratio;
sparkles.push(new Sparkle(px, py, mouse.speedX, mouse.speedY));
}
}
}
mouse.lastX = mouse.x;
mouse.lastY = mouse.y;
});
window.addEventListener('touchmove', (e) => {
const touch = e.touches[0];
mouse.x = touch.clientX;
mouse.y = touch.clientY;
if (mouse.lastX !== null && mouse.lastY !== null) {
mouse.speedX = mouse.x - mouse.lastX;
mouse.speedY = mouse.y - mouse.lastY;
const dist = Math.hypot(mouse.speedX, mouse.speedY);
if (dist > 2) {
const count = Math.min(Math.floor(dist / 3), 3);
for (let i = 0; i < count; i++) {
const ratio = i / count;
const px = mouse.lastX + mouse.speedX * ratio;
const py = mouse.lastY + mouse.speedY * ratio;
sparkles.push(new Sparkle(px, py, mouse.speedX, mouse.speedY));
}
}
}
mouse.lastX = mouse.x;
mouse.lastY = mouse.y;
}, { passive: true });
class Sparkle {
constructor(x, y, vx, vy) {
this.x = x;
this.y = y;
this.vx = vx * 0.15 + (Math.random() - 0.5) * 1.2;
this.vy = vy * 0.15 + (Math.random() - 0.5) * 1.2;
this.alpha = 1;
this.decay = Math.random() * 0.02 + 0.015;
this.size = Math.random() * 5 + 3;
this.angle = Math.random() * Math.PI * 2;
this.rotSpeed = (Math.random() - 0.5) * 0.1;
this.char = Math.random() > 0.45 ? '✦' : '✧';
this.color = Math.random() > 0.35 ? '#d4af37' : '#ffffff';
}
update() {
this.x += this.vx;
this.y += this.vy;
this.vy += 0.02;
this.alpha -= this.decay;
this.angle += this.rotSpeed;
}
draw() {
if (this.alpha <= 0) return;
ctx.save();
ctx.translate(this.x, this.y);
ctx.rotate(this.angle);
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
ctx.fillStyle = this.color;
ctx.globalAlpha = this.alpha * 0.25;
ctx.font = `${this.size * 2}px Arial`;
ctx.fillText(this.char, 0, 0);
ctx.globalAlpha = this.alpha;
ctx.font = `${this.size}px Arial`;
ctx.fillText(this.char, 0, 0);
ctx.restore();
}
}
function animate() {
ctx.clearRect(0, 0, width, height);
for (let i = sparkles.length - 1; i >= 0; i--) {
const s = sparkles[i];
s.update();
if (s.alpha <= 0) {
sparkles.splice(i, 1);
} else {
s.draw();
}
}
requestAnimationFrame(animate);
}
animate();
})();
