async function getDirectAudioUrl(videoId) {
const PIPED_INSTANCES = [
"https://api.piped.private.coffee",
"https://pipedapi.kavin.rocks",
"https://pipedapi.moomoo.me"
];
const INVIDIOUS_INSTANCES = [
"https://invidious.projectsegfau.lt",
"https://invidious.slipfox.xyz",
"https://y.com.sb",
"https://invidious.flokinet.to",
"https://inv.zoomerville.com"
];
const fetchPipedStream = async (instance) => {
const url = `${instance}/streams/${videoId}`;
const res = await fetchWithTimeout(url, 4000);
if (!res.ok) throw new Error("Failed piped stream");
const data = await res.json();
if (data && data.audioStreams && data.audioStreams.length > 0) {
const stream = data.audioStreams[0];
if (stream && stream.url) return stream.url;
}
throw new Error("No audio stream");
};
const fetchInvidiousStream = async (instance) => {
const url = `${instance}/api/v1/videos/${videoId}`;
const res = await fetchWithTimeout(url, 4000);
if (!res.ok) throw new Error("Failed invidious stream");
const data = await res.json();
if (data && data.adaptiveFormats) {
const audioFormat = data.adaptiveFormats.find(f => f.type && f.type.startsWith('audio/'));
if (audioFormat && audioFormat.url) return audioFormat.url;
}
throw new Error("No audio stream");
};
const promises = [];
PIPED_INSTANCES.forEach(instance => {
promises.push(fetchPipedStream(instance));
});
INVIDIOUS_INSTANCES.forEach(instance => {
promises.push(fetchInvidiousStream(instance));
});
return promiseAny(promises);
}
