async function fetchWithTimeout(url, options = {}, timeout = 4000) {
const controller = new AbortController();
const id = setTimeout(() => controller.abort(), timeout);
try {
const response = await fetch(url, {
...options,
signal: controller.signal
});
clearTimeout(id);
return response;
} catch (error) {
clearTimeout(id);
throw error;
}
}
function promiseAny(promises) {
return new Promise((resolve, reject) => {
let errors = [];
let rejectedCount = 0;
if (promises.length === 0) {
reject(new Error("No search URLs provided."));
return;
}
promises.forEach((p, idx) => {
Promise.resolve(p)
.then(resolve)
.catch(err => {
errors[idx] = err;
rejectedCount++;
if (rejectedCount === promises.length) {
reject(new Error("All search instances failed."));
}
});
});
});
}
async function searchYouTube(query) {
const PIPED_INSTANCES = [
"https://api.piped.private.coffee",
"https://pipedapi.kavin.rocks",
"https://pipedapi.moomoo.me"
];
const INVIDIOUS_INSTANCES = [
"https://invidious.projectsegfau.lt",
"https://invidious.slipfox.xyz",
"https://y.com.sb",
"https://invidious.flokinet.to",
"https://inv.zoomerville.com"
];
const fetchPiped = async (instance) => {
const url = `${instance}/search?q=${encodeURIComponent(query)}&filter=all`;
const res = await fetchWithTimeout(url);
if (!res.ok) throw new Error(`Piped status ${res.status} from ${instance}`);
const data = await res.json();
const items = data.items || [];
const streams = items.filter(item => item.type === 'stream');
if (streams && streams.length > 0) {
return streams;
}
throw new Error(`No streams from ${instance}`);
};
const fetchInvidious = async (instance) => {
const url = `${instance}/api/v1/search?q=${encodeURIComponent(query)}`;
const res = await fetchWithTimeout(url);
if (!res.ok) throw new Error(`Invidious status ${res.status} from ${instance}`);
const data = await res.json();
if (Array.isArray(data)) {
const videos = data.filter(item => item.type === 'video' && item.videoId);
if (videos.length > 0) {
return videos.map(item => ({
url: `/watch?v=${item.videoId}`,
title: item.title,
uploaderName: item.author || "YouTube",
duration: item.lengthSeconds || 0
}));
}
}
throw new Error(`No videos from ${instance}`);
};
const promises = [];
PIPED_INSTANCES.forEach(instance => {
promises.push(fetchPiped(instance));
});
INVIDIOUS_INSTANCES.forEach(instance => {
promises.push(fetchInvidious(instance));
});
return promiseAny(promises);
}
