function cleanTrackTitle(title) {
if (!title) return "";
title = title.replace(/[\x22\x27“”„][^\x22\x27“”„]*[\x22\x27“”„]/g, '');
let asciiOnly = title.replace(/[^\x00-\x7F]/g, ' ').trim();
if (asciiOnly.replace(/[^a-zA-Z0-9]/g, '').length >= 3) {
title = asciiOnly;
}
let clean = title.replace(/\s*–\s*/g, ' - ').replace(/\s*—\s*/g, ' - ');
const parts = clean.split(/\s+[\-\|–—]\s+|\s*\|\s*/);
const cleanParts = [];
const junkRegex = /lyrics|lyrical|official|video|audio|visualizer|mv|full\s+song|album|ep|hd|4k|cover|remix|lofi/gi;
parts.forEach(part => {
let pClean = part.replace(/\(.*?\)/g, '').replace(/\[.*?\]/g, '').trim();
pClean = pClean.replace(junkRegex, '').replace(/feat\.|ft\.|prod\./gi, ' ').replace(/\s+/g, ' ').trim();
if (pClean && pClean.length > 1) {
cleanParts.push(pClean);
}
});
if (cleanParts.length >= 2) {
const words = new Set();
const resultParts = [];
cleanParts.slice(0, 3).forEach(p => {
const pLower = p.toLowerCase();
if (!words.has(pLower)) {
words.add(pLower);
resultParts.push(p);
}
});
return resultParts.slice(0, 2).join(' ');
}
return title
.replace(/\(.*?\)/g, '')
.replace(/\[.*?\]/g, '')
.replace(junkRegex, '')
.replace(/feat\.|ft\.|prod\./gi, ' ')
.replace(/[\|\-\/\\\,\:\•]/g, ' ')
.replace(/\s+/g, ' ')
.trim();
}
function parseLRC(lrcText) {
if (!lrcText) return [];
const lines = lrcText.split('\n');
const lyrics = [];
lines.forEach(line => {
const match = line.match(/\[(\d+):(\d+)(?:\.(\d+))?\](.*)/);
if (match) {
const m = parseInt(match[1], 10);
const s = parseInt(match[2], 10);
const msStr = match[3] || '0';
const ms = parseFloat('0.' + msStr);
const time = m * 60 + s + ms;
const text = match[4].trim();
if (text) {
lyrics.push({ time, text });
}
}
});
lyrics.sort((a, b) => a.time - b.time);
return lyrics;
}
