function playGlassBreakSound() {
try {
const AudioContext = window.AudioContext || window.webkitAudioContext;
if (!AudioContext) return;
const ctx = new AudioContext();
const dest = ctx.destination;
const now = ctx.currentTime;
const snapOsc = ctx.createOscillator();
const snapGain = ctx.createGain();
snapOsc.type = 'sine';
snapOsc.frequency.setValueAtTime(2200, now);
snapOsc.frequency.exponentialRampToValueAtTime(100, now + 0.35);
snapGain.gain.setValueAtTime(0.35, now);
snapGain.gain.exponentialRampToValueAtTime(0.001, now + 0.35);
snapOsc.connect(snapGain);
snapGain.connect(dest);
snapOsc.start();
snapOsc.stop(now + 0.4);
const crunchOsc = ctx.createOscillator();
const crunchGain = ctx.createGain();
crunchOsc.type = 'sawtooth';
crunchOsc.frequency.setValueAtTime(150, now);
crunchOsc.frequency.exponentialRampToValueAtTime(30, now + 0.2);
crunchGain.gain.setValueAtTime(0.25, now);
crunchGain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
crunchOsc.connect(crunchGain);
crunchGain.connect(dest);
crunchOsc.start();
crunchOsc.stop(now + 0.25);
const ringOsc = ctx.createOscillator();
const ringGain = ctx.createGain();
ringOsc.type = 'sine';
ringOsc.frequency.setValueAtTime(4500, now);
ringOsc.frequency.setValueAtTime(4800, now + 0.05);
ringGain.gain.setValueAtTime(0.15, now);
ringGain.gain.exponentialRampToValueAtTime(0.001, now + 1.2);
ringOsc.connect(ringGain);
ringGain.connect(dest);
ringOsc.start();
ringOsc.stop(now + 1.2);
const bufferSize = ctx.sampleRate * 0.8;
const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
const data = buffer.getChannelData(0);
for (let i = 0; i < bufferSize; i++) {
data[i] = Math.random() * 2 - 1;
}
const noise = ctx.createBufferSource();
noise.buffer = buffer;
const filter = ctx.createBiquadFilter();
filter.type = 'highpass';
filter.frequency.setValueAtTime(4000, now);
filter.frequency.exponentialRampToValueAtTime(7000, now + 0.5);
const noiseGain = ctx.createGain();
noiseGain.gain.setValueAtTime(0.3, now);
noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.8);
noise.connect(filter);
filter.connect(noiseGain);
noise.start();
noise.stop(now + 0.85);
} catch(err) {
console.log("Audio synthesis blocked:", err);
}
}
