document.getElementById('webhookContact').value = getWebhookUrl(config.webhooks?.contactWebhookUrl) || '';
document.getElementById('webhookIntrusion').value = getWebhookUrl(config.webhooks?.intrusionWebhookUrl) || '';
document.getElementById('webhookDuration').value = getWebhookUrl(config.webhooks?.durationWebhookUrl) || '';
