document.getElementById('webhookAdminLogin').value = getWebhookUrl(config.webhooks?.adminLoginWebhookUrl) || '';
document.getElementById('webhookAdminChanges').value = getWebhookUrl(config.webhooks?.adminChangesWebhookUrl) || '';
document.getElementById('pageTitle').value = config.seo?.pageTitle || '';
document.getElementById('profileUsername').value = config.profile?.username || '';
document.getElementById('profileAvatar').value = config.profile?.avatarUrl || '';
document.getElementById('profileDecoration').value = config.profile?.avatarDecorationUrl || '';
document.getElementById('profileVerified').checked = !!config.profile?.isVerified;
document.getElementById('socialFacebook').value = config.socials?.facebook || '';
document.getElementById('socialInstagram').value = config.socials?.instagram || '';
document.getElementById('socialTiktok').value = config.socials?.tiktok || '';
document.getElementById('socialThreads').value = config.socials?.threads || '';
