if (oldT.isYouTube !== newT.isYouTube) tDiffs.push(`isYouTube: \`${oldT.isYouTube}\` ➔ \`${newT.isYouTube}\``);
if (oldT.isBackgroundVideo !== newT.isBackgroundVideo) tDiffs.push(`isBackgroundVideo: \`${oldT.isBackgroundVideo}\` ➔ \`${newT.isBackgroundVideo}\``);
if (!areLyricsEqual(oldT.lyrics, newT.lyrics)) tDiffs.push(`Lyrics modified`);
