function open2FAVerificationModal(secret, onSuccessCallback) {
ensure2FAModalExists();
const modal = document.getElementById('twoFactorModal');
const passwordInput = document.getElementById('twoFactorPasswordInput');
const input = document.getElementById('twoFactorInput');
const errorEl = document.getElementById('twoFactorError');
const cancelBtn = document.getElementById('twoFactorCancelBtn');
const verifyBtn = document.getElementById('twoFactorVerifyBtn');
modal.style.display = 'flex';
passwordInput.value = '';
input.value = '';
passwordInput.focus();
errorEl.style.display = 'none';
const newCancelBtn = cancelBtn.cloneNode(true);
const newVerifyBtn = verifyBtn.cloneNode(true);
cancelBtn.parentNode.replaceChild(newCancelBtn, cancelBtn);
verifyBtn.parentNode.replaceChild(newVerifyBtn, verifyBtn);
newCancelBtn.addEventListener('click', () => {
modal.style.display = 'none';
});
const handleVerify = async () => {
const passwordVal = passwordInput.value.trim();
const code = input.value.trim().replace(/\s/g, '');
if (!passwordVal) {
errorEl.style.display = 'block';
errorEl.textContent = '❌ Please enter your admin password.';
passwordInput.focus();
return;
}
if (code.length !== 6) {
errorEl.style.display = 'block';
errorEl.textContent = '❌ Please enter a 6-digit 2FA code.';
input.focus();
return;
}
try {
const enteredPassHash = await sha256(passwordVal);
const expectedPassHash = window.portfolioConfig?.security?.adminPasswordHash || "fd9545ccd948144d25faa8d4545b4f9c42b669397255ca2f849568b6582004e9";
if (enteredPassHash !== expectedPassHash) {
errorEl.style.display = 'block';
errorEl.textContent = '❌ Incorrect Password. Please try again.';
passwordInput.focus();
return;
}
if (!secret) throw new Error("No secret set");
const cleanSecret = secret.replace(/[^A-Z2-7]/gi, '').toUpperCase();
let totp = new OTPAuth.TOTP({
issuer: 'Apollyon Portfolio',
label: 'Owner',
algorithm: 'SHA1',
digits: 6,
period: 30,
secret: OTPAuth.Secret.fromBase32(cleanSecret)
});
let delta = totp.validate({
token: code,
window: 10
});
if (delta !== null) {
modal.style.display = 'none';
onSuccessCallback();
} else {
errorEl.style.display = 'block';
errorEl.textContent = '❌ Invalid 2FA code. Please try again.';
input.focus();
}
} catch(err) {
console.error("Verification error:", err);
errorEl.style.display = 'block';
errorEl.textContent = '❌ Verification System failed.';
}
};
newVerifyBtn.addEventListener('click', handleVerify);
const handleKeypress = (e) => {
if (e.key === 'Enter') {
handleVerify();
}
};
passwordInput.addEventListener('keypress', handleKeypress);
input.addEventListener('keypress', handleKeypress);
}
